      "output": "let _ac=null;\nfunction sfx(n){\n  if(!_ac) _ac=new AudioContext();\n  const t=_ac.currentTime, o=_ac.createOscillator(), g=_ac.createGain();\n  o.connect(g); g.connect(_ac.destination);\n  if(n==='catch'){o.type='square';o.frequency.setValueAtTime(400,t);o.frequency.exponentialRampToValueAtTime(800,t+.08);g.gain.value=.3;o.start(t);o.stop(t+.1);}\n  else if(n==='gold'){o.type='triangle';o.frequency.value=523;g.gain.value=.25;o.start(t);o.stop(t+.2);const o2=_ac.createOscillator(),g2=_ac.createGain();o2.type='triangle';o2.frequency.value=784;o2.connect(g2);g2.connect(_ac.destination);g2.gain.value=.25;o2.start(t);o2.stop(t+.2);}\n  else if(n==='bump'){o.type='sine';o.frequency.value=80;g.gain.setValueAtTime(.5,t);g.gain.exponentialRampToValueAtTime(.01,t+.2);o.start(t);o.stop(t+.25);}\n  else if(n==='splash'){const b=_ac.createBuffer(1,_ac.sampleRate*.2,_ac.sampleRate),d=b.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=(Math.random()*2-1)*(1-i/d.length);const s=_ac.createBufferSource(),f=_ac.createBiquadFilter();s.buffer=b;f.type='lowpass';f.frequency.value=2000;s.connect(f);f.connect(_ac.destination);s.start(t);}\n  else if(n==='beep'){o.type='sine';o.frequency.value=880;g.gain.value=.3;o.start(t);o.stop(t+.15);}\n  else if(n==='whistle'){o.type='sine';o.frequency.value=1200;g.gain.setValueAtTime(.3,t);g.gain.exponentialRampToValueAtTime(.01,t+.5);o.start(t);o.stop(t+.5);}\n}"
