      "output": "<!DOCTYPE html>\n<html><head><meta charset=\"UTF-8\"><style>*{margin:0;padding:0}body{background:#0a1628;overflow:hidden;display:flex;align-items:center;justify-content:center;height:100vh}canvas{max-width:100vw;max-height:100vh}</style></head><body>\n<canvas id=\"c\" width=\"800\" height=\"600\"></canvas>\n<script>\nconst cv=document.getElementById('c'),cx=cv.getContext('2d');\nlet _ac=null;\nfunction sfx(n){\n  if(!_ac) _ac=new AudioContext();\n  const t=_ac.currentTime,o=_ac.createOscillator(),g=_ac.createGain();\n  o.connect(g);g.connect(_ac.destination);\n  if(n==='catch'){o.type='square';o.frequency.setValueAtTime(400,t);o.frequency.exponentialRampToValueAtTime(800,t+.08);g.gain.value=.3;o.start(t);o.stop(t+.1);}\n  else if(n==='gold'){o.type='triangle';o.frequency.value=523;g.gain.value=.25;o.start(t);o.stop(t+.2);const o2=_ac.createOscillator(),g2=_ac.createGain();o2.type='triangle';o2.frequency.value=784;o2.connect(g2);g2.connect(_ac.destination);g2.gain.value=.25;o2.start(t);o2.stop(t+.2);}\n  else if(n==='bump'){o.type='sine';o.frequency.value=80;g.gain.setValueAtTime(.5,t);g.gain.exponentialRampToValueAtTime(.01,t+.2);o.start(t);o.stop(t+.25);}\n  else if(n==='splash'){const b=_ac.createBuffer(1,_ac.sampleRate*.2,_ac.sampleRate),d=b.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=(Math.random()*2-1)*(1-i/d.length);const s=_ac.createBufferSource(),f=_ac.createBiquadFilter();s.buffer=b;f.type='lowpass';f.frequency.value=2000;s.connect(f);f.connect(_ac.destination);s.start(t);}\n  else if(n==='beep'){o.type='sine';o.frequency.value=880;g.gain.value=.3;o.start(t);o.stop(t+.15);}\n  else if(n==='whistle'){o.type='sine';o.frequency.value=1200;g.gain.setValueAtTime(.3,t);g.gain.exponentialRampToValueAtTime(.01,t+.5);o.start(t);o.stop(t+.5);}\n}\nconst F=0.3,MAXV=250,ACC=400,R=18,BW=800,BH=600,RESPAWN=2;\nfunction step(P,I,dt){\nfor(let i=0;i<P.length;i++){\n if(P[i].out){P[i].outT+=dt;if(P[i].outT>=RESPAWN){P[i].out=false;P[i].outT=0;P[i].x=BW/2;P[i].y=BH/2;P[i].vx=0;P[i].vy=0;}continue;}\n const d=I[i]||{ax:0,ay:0};\n P[i].vx+=d.ax*ACC*dt;P[i].vy+=d.ay*ACC*dt;\n const s=Math.exp(-F*dt);P[i].vx*=s;P[i].vy*=s;\n const sp=Math.hypot(P[i].vx,P[i].vy);\n if(sp>MAXV){P[i].vx*=MAXV/sp;P[i].vy*=MAXV/sp;}\n P[i].x+=P[i].vx*dt;P[i].y+=P[i].vy*dt;\n if(P[i].x<R||P[i].x>BW-R||P[i].y<R||P[i].y>BH-R){P[i].out=true;P[i].outT=0;}\n}\nfor(let i=0;i<P.length;i++)for(let j=i+1;j<P.length;j++){\n if(P[i].out||P[j].out)continue;\n const dx=P[j].x-P[i].x,dy=P[j].y-P[i].y,d=Math.hypot(dx,dy);\n if(d<2*R&&d>0){const nx=dx/d,ny=dy/d,ov=(2*R-d)/2;\n P[i].x-=nx*ov;P[i].y-=ny*ov;P[j].x+=nx*ov;P[j].y+=ny*ov;\n const dvn=(P[i].vx-P[j].vx)*nx+(P[i].vy-P[j].vy)*ny;\n if(dvn>0){P[i].vx-=dvn*nx;P[i].vy-=dvn*ny;P[j].vx+=dvn*nx;P[j].vy+=dvn*ny;}}\n}}\nconst COLORS=['#e53e3e','#3182ce','#38a169','#ecc94b'];\nconst KEYS=[['w','a','s','d'],['arrowup','arrowleft','arrowdown','arrowright'],['i','j','k','l'],['8','4','5','6']];\nlet state='menu',np=4,score=[0,0,0,0],P=[],fish=[],cd=3,cdT=0,pt=60,fT=0,fishCount=0,ready=false;\nlet keys={};\ndocument.addEventListener('click',()=>{ready=true;});\ndocument.addEventListener('keydown',e=>{keys[e.key.toLowerCase()]=true;if(!ready)return;if(state==='menu'){if(e.key===' ')startGame();else if(e.key==='2')np=2;else if(e.key==='3')np=3;else if(e.key==='4')np=4;}else if(state==='end'&&e.key===' '){score=[0,0,0,0];state='menu';}});\ndocument.addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false;});\nfunction startGame(){P=[];for(let i=0;i<np;i++)P.push({x:BW/2,y:BH/2,vx:0,vy:0,out:false,outT:0});fish=[];score=[0,0,0,0];cd=3;cdT=0;pt=60;fT=0;fishCount=0;state='countdown';}\nfunction spawnFish(){if(fish.length>=8)return;fish.push({x:50+Math.random()*(BW-100),y:50+Math.random()*(BH-100),gold:Math.random()<0.2});}\nfunction getInputs(){let ins=[];for(let i=0;i<np;i++){const k=KEYS[i];ins.push({ax:(keys[k[1]]?1:0)-(keys[k[3]]?1:0),ay:(keys[k[2]]?1:0)-(keys[k[0]]?1:0)});}return ins;}\nfunction drawIce(){cx.fillStyle='#1a5276';cx.fillRect(0,0,BW,BH);cx.fillStyle='#a8d8ea';cx.beginPath();cx.roundRect(10,10,BW-20,BH-20,20);cx.fill();cx.strokeStyle='rgba(255,255,255,0.3)';cx.lineWidth=1;cx.beginPath();cx.moveTo(200,150);cx.lineTo(350,300);cx.lineTo(500,200);cx.stroke();cx.beginPath();cx.moveTo(400,400);cx.lineTo(550,500);cx.stroke();cx.fillStyle='rgba(255,255,255,0.4)';cx.fillRect(15,12,BW-30,4);}\nfunction drawPenguin(p,i){cx.save();cx.translate(p.x,p.y);const sp=Math.hypot(p.vx,p.vy);if(sp>10)cx.rotate(Math.atan2(p.vy,p.vx)+Math.PI/2);cx.fillStyle=COLORS[i];cx.beginPath();cx.ellipse(0,0,R,R*1.2,0,0,Math.PI*2);cx.fill();cx.fillStyle='#fff';cx.beginPath();cx.ellipse(0,3,R*0.55,R*0.65,0,0,Math.PI*2);cx.fill();cx.fillStyle='#333';cx.beginPath();cx.moveTo(0,-R*1.1);cx.lineTo(-4,-R*1.4);cx.lineTo(4,-R*1.4);cx.fill();cx.fillStyle='#222';cx.beginPath();cx.ellipse(-R*0.8,0,5,8,0,0,Math.PI*2);cx.fill();cx.beginPath();cx.ellipse(R*0.8,0,5,8,0,0,Math.PI*2);cx.fill();cx.fillStyle=COLORS[i];cx.fillRect(-8,-R*0.9,16,5);cx.restore();}\nfunction drawFish(f){cx.save();cx.translate(f.x,f.y);cx.fillStyle=f.gold?'#f6c344':'#999';cx.beginPath();cx.ellipse(0,0,12,7,0,0,Math.PI*2);cx.fill();cx.beginPath();cx.moveTo(12,0);cx.lineTo(18,-6);cx.lineTo(18,6);cx.fill();cx.restore();}\nfunction drawScore(){for(let i=0;i<np;i++){const x=i%2===0?10:BW-110,y=i<2?10:BH-35;cx.fillStyle='rgba(0,0,0,0.5)';cx.fillRect(x,y,100,25);cx.fillStyle='#fff';cx.font='12px monospace';cx.fillText('P'+(i+1)+':'+score[i],x+5,y+17);}}\nfunction rank(){let a=[];for(let i=0;i<np;i++)a.push({i,s:score[i]});a.sort((x,y)=>y.s-x.s||x.i-y.i);return a;}\nlet last=0;\nfunction loop(t){const dt=Math.min((t-last)/1000,0.05);last=t;\nif(state==='menu'){cx.fillStyle='#1a5276';cx.fillRect(0,0,BW,BH);cx.fillStyle='#a8d8ea';cx.fillRect(10,10,BW-20,BH-20);cx.fillStyle='#fff';cx.font='28px monospace';cx.textAlign='center';cx.fillText('Ice Fish Grab',BW/2,BH/2-40);cx.font='18px monospace';cx.fillText('Players: '+np+'  (2/3/4 to change)',BW/2,BH/2);cx.fillText('Press SPACE to start',BW/2,BH/2+40);cx.textAlign='left';}\nelse if(state==='countdown'){drawIce();cdT+=dt;if(cdT>=1){cdT=0;cd--;if(cd<=0){state='play';sfx('whistle');}else sfx('beep');}if(cd>0){cx.fillStyle='rgba(0,0,0,0.3)';cx.fillRect(0,0,BW,BH);cx.fillStyle='#fff';cx.font='72px monospace';cx.textAlign='center';cx.fillText(cd,BW/2,BH/2+20);cx.textAlign='left';}}\nelse if(state==='play'){pt-=dt;if(pt<=0){state='end';sfx('whistle');}const ins=getInputs();step(P,ins,dt);fT+=dt;if(fT>=1.5){fT=0;spawnFish();}for(let i=fish.length-1;i>=0;i--){const f=fish[i];for(let p=0;p<np;p++){if(P[p].out)continue;const d=Math.hypot(P[p].x-f.x,P[p].y-f.y);if(d<R+12){score[p]+=f.gold?3:1;sfx(f.gold?'gold':'catch');fish.splice(i,1);break;}}}drawIce();for(let f of fish)drawFish(f);for(let i=0;i<np;i++)if(!P[i].out)drawPenguin(P[i],i);drawScore();cx.fillStyle='#fff';cx.font='16px monospace';cx.textAlign='center';cx.fillText(Math.ceil(pt)+'s',BW/2,30);cx.textAlign='left';}\nelse if(state==='end'){drawIce();const r=rank();cx.fillStyle='rgba(0,0,0,0.5)';cx.fillRect(0,0,BW,BH);cx.fillStyle='#fff';cx.font='28px monospace';cx.textAlign='center';cx.fillText('Results',BW/2,80);cx.font='20px monospace';for(let i=0;i<np;i++){cx.fillText((i+1)+'. P'+(r[i].i+1)+'  '+r[i].s+' pts',BW/2,140+i*35);}cx.fillText('Press SPACE to replay',BW/2,140+np*35+20);cx.textAlign='left';}\nrequestAnimationFrame(loop);}\nrequestAnimationFrame(loop);\n</script>\n</body></html>"
